INSERT INTO sessions (id,date,program_id,day,notes) VALUES ('sb04244','2025-10-20','history:snowboard','Recovery/unstructured','Park/Rock (Rewind) · LoveZone · Patchy early season snow, rocks & sticks, sprinkling snow, late day slush/sticky');
INSERT INTO sessions (id,date,program_id,day,notes) VALUES ('sb04247','2025-10-23','history:snowboard','Dry land practice','Daily (FeelGood) · Room · n/a');
INSERT INTO sessions (id,date,program_id,day,notes) VALUES ('sb04249','2025-10-25','history:snowboard','Recovery/unstructured','Daily (FeelGood) · Keystone · Surprisingly good white ribbon!');
INSERT INTO sessions (id,date,program_id,day,notes) VALUES ('sb04250','2025-10-28','history:snowboard','Jumps','Daily (FeelGood) · A Basin · Also a surprisingly good white ribbon! Fresh coat of overnight snow was so fluffy and the cherry on top.');
INSERT INTO sessions (id,date,program_id,day,notes) VALUES ('sb04257','2025-10-30','history:snowboard','Park/freestyle','Daily (FeelGood) · Keystone · Started out with hoodie weather and midday went into a really nice single layer temps. Bluebird skies. Overall excellent.');
INSERT INTO sessions (id,date,program_id,day,notes) VALUES ('sb04265','2025-11-02','history:snowboard','Park/freestyle','Daily (FeelGood) · Keystone · HOT. Glad I only wore one layer. Interesting having slush right now, not too interfering though. Ate a big sandwich beforehand and I think that sat in my stomach in not a useful way... Vaguely felt like I had to poop the whole time. Lesson learned. Lol. Also got vaccines for EMT clinicals beforehand and in retrospect that might''ve been fucking with me physically too.');
INSERT INTO sessions (id,date,program_id,day,notes) VALUES ('sb04270','2025-11-06','history:snowboard','Recovery/unstructured','Daily (FeelGood) · Keystone · Warm (30F) but cloudy and windy so not really slushy. I''d rate it good.');
INSERT INTO sessions (id,date,program_id,day,notes) VALUES ('sb04271','2025-11-08','history:snowboard','Recovery/unstructured','Daily (FeelGood) · Breck · Holy mother of bad conditions 😅 So much ice and weird graupel-like snow piles. Called it early because it felt like an injury waiting to happen.');
