INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04245','sb04244','board-grab','landed: Yes · confidence: High · Next time, more air. Different grabs. Jump up, don''t just pull legs up.','2025-10-20');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04246','sb04244','small-tube','landed: Shaky · confidence: Low · Only got it once. Used to be easy - lacking confidence. Keep at it and work on the headspace!','2025-10-20');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04248','sb04247','180s-fs-bs','landed: Yes · confidence: High · This one feels easy, but right groin is complaining. Think I strained it the other day with an improper butter. Looking forward to trying these on snow. Felt good in all directions - fs, bs, regular, switch.','2025-10-23');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04251','sb04250','board-grab','landed: Yes · confidence: High · Progression is straightforward - bigger jumps, more air. Felt better at using the kicker to pop off instead of just jumping in place and pulling legs up.','2025-10-28');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04252','sb04250','method-mini','landed: Yes · confidence: High · Likewise. Bigger jumps, more air. Kick out back leg more for STEEZ.','2025-10-28');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04253','sb04250','butter','landed: Shaky · confidence: Low · Tried this maybe twice. Fun. More reps needed!','2025-10-28');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04254','sb04250','compass-360','landed: Yes · confidence: Medium · Tried this a couple times - I can fully spin competently but I''m not sure I''m doing the "compass" style part right. More reps needed!','2025-10-28');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04255','sb04250','flat-180','landed: Yes · confidence: High · Surprisingly very easy - gym work absolutely showing!','2025-10-28');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04256','sb04250','switch','landed: Shaky · confidence: Low · Reps, reps, reps. I think this is 90% a confidence issue.','2025-10-28');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04258','sb04257','dance-floor','landed: Yes · confidence: High','2025-10-30');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04259','sb04257','rainbow-box','landed: Yes · confidence: High','2025-10-30');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04260','sb04257','tube','landed: Yes · confidence: High','2025-10-30');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04261','sb04257','wide-down-rail','landed: Yes · confidence: High','2025-10-30');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04262','sb04257','wide-up-rail','landed: Yes · confidence: High · With this and all above, very surprised by how natural it all felt. Expected to be coming back farther behind but this was all super smooth!','2025-10-30');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04263','sb04257','fs-board-slide-rainbow-box','landed: Yes · confidence: Medium · Honestly? First time ever landing this. And it felt great. Cued myself to get low from the knees and it immediately clicked. Just a matter of confidence and reps. Otherwise I think I have the technique and ability. WOW I really didn''t think I''d be progressing almost immediately after being released to return to sport. Can''t complain in the slightest.','2025-10-30');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04264','sb04257','180-to-wall','landed: Yes · confidence: Medium · Ditto above. Amazing day!','2025-10-30');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04266','sb04265','fs-board-slide-rainbow-box','landed: Yes · confidence: Medium','2025-11-02');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04267','sb04265','180-to-wall','landed: Yes · confidence: Medium · Redid these as a touch up. Heavy stomach kinda interfered with my mind-body connection, though. Rotations felt stiff.','2025-11-02');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04268','sb04265','fs-board-slide-tube','landed: Shaky · confidence: Medium · Almost got it once and then I guess I''m tired and heavy (?) so it went downhill from there. That''s okay, it''s not always up and up. Try again next time without a heavy stomach! I didn''t really set myself up for success today 😅','2025-11-02');
INSERT INTO sets (id,session_id,exercise_id,notes,logged_at) VALUES ('s04269','sb04265','thin-tube','landed: Shaky · confidence: Low · Heavy landing (coming from side instead of head on) and didn''t ride the whole thing. Try again!','2025-11-02');
